INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Kundenbeziehungen > Ethik
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist ethisches Verhalten in Kundenbeziehungen gesetzlich vorgeschrieben?', 2, '[{"text": "Nein", "correct": true, "because": "Ethik geht über gesetzliche Pflichten hinaus"}, {"text": "Ja", "correct": false, "because": "Gesetze regeln nicht direkt Ethik"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Unternehmen ethische Standards in Kundenbeziehungen ignorieren, wenn dies den Gewinn maximiert?', 2, '[{"text": "Nein", "correct": true, "because": "Ethik schützt langfristig Reputation und Vertrauen"}, {"text": "Ja", "correct": false, "because": "Kurzfristiger Gewinn gefährdet Nachhaltigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ethisches Verhalten in Kundenbeziehungen auch die Wahrung von Kundeninteressen umfassen?', 2, '[{"text": "Ja", "correct": true, "because": "Fairness gegenüber Kunden ist ethischer Grundsatz"}, {"text": "Nein", "correct": false, "because": "Kundeninteressen sind zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Können ethische Prinzipien in Kundenbeziehungen mit gesetzlichen Vorgaben in Konflikt stehen?', 2, '[{"text": "Ja", "correct": true, "because": "Ethik kann strengere Maßstäbe setzen als Gesetze"}, {"text": "Nein", "correct": false, "because": "Konflikte sind möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es ethisch vertretbar, Kunden über Produkteigenschaften zu täuschen, wenn dies nicht gesetzlich verboten ist?', 2, '[{"text": "Nein", "correct": true, "because": "Täuschung widerspricht ethischer Integrität"}, {"text": "Ja", "correct": false, "because": "Ethik verlangt Ehrlichkeit"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher ethische Grundsatz steht in Kundenbeziehungen im Vordergrund?', 2, '[{"text": "Transparenz", "correct": true, "because": "Fördert Vertrauen und Fairness"}, {"text": "Gewinnmaximierung", "correct": false, "because": "Eher wirtschaftlich"}, {"text": "Konkurrenzvorteil", "correct": false, "because": "Nicht ethisch zentriert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten wäre in Kundenbeziehungen ethisch unvertretbar?', 3, '[{"text": "Verschleierung von Produktmängeln", "correct": true, "because": "Verletzt Ehrlichkeit und Vertrauen"}, {"text": "Offenlegung von Preiskalkulationen", "correct": false, "because": "Fördert Transparenz"}, {"text": "Rabattgewährung bei Reklamationen", "correct": false, "because": "Zeigt Kulanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Ethik in Kundenbeziehungen primär?', 2, '[{"text": "Langfristiges Vertrauen schaffen", "correct": true, "because": "Ethik stärkt Beziehungen"}, {"text": "Kurzfristige Umsätze steigern", "correct": false, "because": "Nicht ethisches Ziel"}, {"text": "Kosten senken", "correct": false, "because": "Wirtschaftlich, nicht ethisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt der Ethik ist in Kundenbeziehungen besonders relevant?', 2, '[{"text": "Fairness", "correct": true, "because": "Gleicht Interessen aus"}, {"text": "Effizienz", "correct": false, "because": "Operativer Fokus"}, {"text": "Wettbewerbsstärke", "correct": false, "because": "Nicht ethisch primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die größte Konsequenz eines ethischen Verstoßes in Kundenbeziehungen?', 2, '[{"text": "Verlust von Kundenvertrauen", "correct": true, "because": "Vertrauen ist schwer wiederherzustellen"}, {"text": "Geringere Produktionskosten", "correct": false, "because": "Keine ethische Folge"}, {"text": "Höhere Marktanteile", "correct": false, "because": "Eher Verlust droht"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche ethischen Prinzipien sollten Kundenbeziehungen leiten?', 4, '[{"text": "Ehrlichkeit", "correct": true, "because": "Verhindert Täuschung"}, {"text": "Respekt", "correct": true, "because": "Wertschätzt Kunden"}, {"text": "Verantwortung", "correct": true, "because": "Schützt Kundeninteressen"}, {"text": "Profitstreben", "correct": false, "because": "Kein ethisches Prinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Handlungen entsprechen ethischen Standards in Kundenbeziehungen?', 3, '[{"text": "Offenlegung von Risiken", "correct": true, "because": "Fördert Transparenz"}, {"text": "Schutz von Kundendaten", "correct": true, "because": "Respektiert Privatsphäre"}, {"text": "Kulanz bei Fehlern", "correct": true, "because": "Zeigt Verantwortung"}, {"text": "Überteuerte Preise", "correct": false, "because": "Unfair gegenüber Kunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann ein Mangel an Ethik in Kundenbeziehungen haben?', 4, '[{"text": "Reputationsschaden", "correct": true, "because": "Vertrauen sinkt"}, {"text": "Kundenabwanderung", "correct": true, "because": "Unzufriedenheit steigt"}, {"text": "Rechtliche Konflikte", "correct": true, "because": "Unethisches kann illegal sein"}, {"text": "Gesteigerte Effizienz", "correct": false, "because": "Keine positive Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte der Ethik sind in Kundenbeziehungen besonders herausfordernd?', 3, '[{"text": "Interessenkonflikte", "correct": true, "because": "Gewinn vs. Kundenwohl"}, {"text": "Datenschutz", "correct": true, "because": "Sensibilität der Daten"}, {"text": "Transparenz", "correct": true, "because": "Offenheit vs. Wettbewerb"}, {"text": "Produktivität", "correct": false, "because": "Kein ethischer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen fördern ethisches Verhalten in Kundenbeziehungen?', 3, '[{"text": "Schulungen zu Ethik", "correct": true, "because": "Sensibilisiert Mitarbeiter"}, {"text": "Klare Verhaltenskodizes", "correct": true, "because": "Leitet Handeln"}, {"text": "Kundenfeedback einholen", "correct": true, "because": "Spiegelt Bedürfnisse"}, {"text": "Preisabsprachen", "correct": false, "because": "Unethisch und illegal"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ethik in Kundenbeziehungen fördert Vertrauen. b) Sie ist nur für große Unternehmen relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vertrauen ja, Ethik gilt allgemein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ctragen korrekt? a) Transparenz ist ein ethisches Prinzip in Kundenbeziehungen. b) Ethik steht immer im Einklang mit gesetzlichen Vorgaben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Transparenz ja, Konflikte möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ethik verlangt den Schutz von Kundendaten. b) Täuschung ist ethisch, wenn sie legal ist.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datenschutz ja, Täuschung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ethik kann den Unternehmensgewinn kurzfristig senken. b) Kundeninteressen sind ethisch irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kurzfristige Kosten ja, Kundeninteressen zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein ethischer Verstoß kann die Reputation schädigen. b) Ethik ist in Kundenbeziehungen optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Reputation ja, Ethik essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

